#!/usr/bin/env python3
"""
Minimal Anthropic → OpenAI-compatible proxy.
Lets Hermes and MiroFish use Anthropic's API via the OpenAI format.
Run: python3 tools/anthropic_proxy.py
Then set: LLM_BASE_URL=http://localhost:7070/v1, LLM_API_KEY=any
"""

import json
import os
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
import urllib.request

# Load API key
try:
    from dotenv import load_dotenv
    load_dotenv(Path(__file__).parent.parent / ".env")
except ImportError:
    pass

ANTHROPIC_KEY = os.environ.get("ANTHROPIC_API_KEY", "")
PORT = 7070
MODEL_MAP = {
    "gpt-4o": "claude-sonnet-4-6",
    "gpt-4o-mini": "claude-haiku-4-5-20251001",
    "gpt-4": "claude-sonnet-4-6",
    "gpt-3.5-turbo": "claude-haiku-4-5-20251001",
    "qwen2.5:32b": "claude-sonnet-4-6",
    "qwen2.5:7b": "claude-haiku-4-5-20251001",
}


def openai_to_anthropic(openai_req: dict) -> dict:
    model_in = openai_req.get("model", "claude-haiku-4-5-20251001")
    model = MODEL_MAP.get(model_in, model_in)
    if not model.startswith("claude-"):
        model = "claude-haiku-4-5-20251001"

    messages = openai_req.get("messages", [])
    system = ""
    anthropic_messages = []
    for m in messages:
        role = m.get("role", "user")
        content = m.get("content", "")
        if role == "system":
            system = content
        elif role in ("user", "assistant"):
            anthropic_messages.append({"role": role, "content": content})

    return {
        "model": model,
        "max_tokens": openai_req.get("max_tokens", 2048),
        "messages": anthropic_messages,
        **({"system": system} if system else {}),
        **({"temperature": openai_req["temperature"]} if "temperature" in openai_req else {}),
        **({"stream": True} if openai_req.get("stream") else {}),
    }


def anthropic_to_openai(anthropic_resp: dict, model: str) -> dict:
    content = ""
    if anthropic_resp.get("content"):
        for block in anthropic_resp["content"]:
            if block.get("type") == "text":
                content += block.get("text", "")

    return {
        "id": anthropic_resp.get("id", "chatcmpl-sowl"),
        "object": "chat.completion",
        "model": model,
        "choices": [{
            "index": 0,
            "message": {"role": "assistant", "content": content},
            "finish_reason": anthropic_resp.get("stop_reason", "stop"),
        }],
        "usage": {
            "prompt_tokens": anthropic_resp.get("usage", {}).get("input_tokens", 0),
            "completion_tokens": anthropic_resp.get("usage", {}).get("output_tokens", 0),
        }
    }


class ProxyHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Quiet

    def do_GET(self):
        if self.path == "/v1/models":
            models = {"object": "list", "data": [
                {"id": "claude-sonnet-4-6", "object": "model"},
                {"id": "claude-haiku-4-5-20251001", "object": "model"},
            ]}
            self._json(200, models)
        else:
            self._json(200, {"status": "Anthropic proxy running", "port": PORT})

    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = json.loads(self.rfile.read(length))

        if "/chat/completions" in self.path:
            model_in = body.get("model", "gpt-4o-mini")
            anthropic_req = openai_to_anthropic(body)

            req = urllib.request.Request(
                "https://api.anthropic.com/v1/messages",
                data=json.dumps(anthropic_req).encode(),
                headers={
                    "x-api-key": ANTHROPIC_KEY,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                method="POST"
            )

            try:
                with urllib.request.urlopen(req, timeout=60) as resp:
                    anthropic_resp = json.loads(resp.read())
                openai_resp = anthropic_to_openai(anthropic_resp, model_in)
                self._json(200, openai_resp)
            except Exception as e:
                self._json(500, {"error": str(e)})
        else:
            self._json(404, {"error": "not found"})

    def _json(self, code, data):
        body = json.dumps(data).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


if __name__ == "__main__":
    print(f"🦉 Anthropic→OpenAI proxy on port {PORT}")
    print(f"   Set: LLM_BASE_URL=http://localhost:{PORT}/v1")
    print(f"   API key: {'✅ found' if ANTHROPIC_KEY else '❌ missing'}")
    HTTPServer(("0.0.0.0", PORT), ProxyHandler).serve_forever()

