def ask_local(context: str, prompt: str) -> str:
    """Ask Qwopus (local 27B model) — zero API cost, sovereign cognition."""
    global _qwopus_model, _qwopus_tokenizer
    try:
        from mlx_lm import load, generate
        qwopus_flag = SEED_DIR / "logs/qwopus_integrated.flag"
        if not qwopus_flag.exists():
            return None

        # Cache model in memory across calls
        if _qwopus_model is None:
            log.info("Loading Qwopus 27B into memory (one-time, cached)...")
            _qwopus_model, _qwopus_tokenizer = load(
                "mlx-community/Qwen3.5-27B-Claude-4.6-Opus-Distilled-MLX-4bit"
            )
            log.info("Qwopus loaded and cached")

        resp = generate(_qwopus_model, _qwopus_tokenizer, prompt=prompt, max_tokens=600, verbose=False)

        # Strip <think>...</think> blocks (Qwopus reasoning mode)
        import re
        resp_clean = re.sub(r'<think>.*?</think>', '', resp, flags=re.DOTALL).strip()

        # Extract JSON
        m = re.search(r'\{[^{}]*"directive"[^{}]*\}', resp_clean, re.DOTALL)
        if not m:
            m = re.search(r'\{.*\}', resp_clean, re.DOTALL)
        if m:
            return m.group()

        # If no JSON but has text, wrap it as a directive
