            return json.dumps({
                "directive": resp_clean[:100],
                "type": "bash",
                "command": "echo 'Qwopus directive (non-JSON): see log'",
                "why_love": "Local sovereign cognition active"
            })
        return None
    except Exception as e:
        log.warning(f"Qwopus ask failed: {e}")
        return None

