      '''

new = '''    // Fast local embedding for cross-pollination triggering (no API wait)
    function quickEmbed(text) {
      const words = text.toLowerCase().split(/\\s+/).filter(w => w.length > 2);
      const vec = new Float32Array(64).fill(0);
      words.forEach((w, i) => {
        const hash = [...w].reduce((h, c) => (h * 31 + c.charCodeAt(0)) & 0x7fffffff, 0);
        vec[hash % 64] += 1.0 / (1 + i * 0.1);
      });
      const norm = Math.sqrt(vec.reduce((s, v) => s + v*v, 0)) || 1;
      return Array.from(vec).map(v => v / norm);
    }

    async function embedTexts(texts, apiKey) {
      // Use fast local embeddings immediately, Gemini runs in background for quality
      if (!apiKey) {
        return texts.map(t => quickEmbed(t));
      }
