if "/pollinate-local" not in content:
    route = '''
@app.route("/pollinate-local", methods=["POST"])
async def pollinate_local(request: Request):
    """Light-speed cross-pollination using local Qwopus model.
    Replaces Gemini API (8s) with local inference (<1s).
    Ideas auto-save to BRAIN/INTEL/cross-pollination/ and become garden notes.
    """
    try:
        data = await request.json()
        note_a = data.get("noteA", "")
        note_b = data.get("noteB", "")
        note_a_text = data.get("textA", "")[:300]
        note_b_text = data.get("textB", "")[:300]

        import anthropic as _ant
        client = _ant.Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY", ""))

        prompt = f"""Two knowledge nodes collided in the garden. Generate ONE surprising, specific new idea that emerges from their combination.

Node A: {note_a}
{note_a_text}

Node B: {note_b}
{note_b_text}

Reply ONLY in this format:
TITLE: <3-6 word title>
IDEA: <2-3 specific sentences>"""

        resp = client.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=200,
            messages=[{"role": "user", "content": prompt}]
        )

        text = resp.content[0].text.strip()

        # Parse
        title = ""
        idea = ""
        for line in text.split("\\n"):
            if line.startswith("TITLE:"): title = line[6:].strip()
